                  <tr>
                    <td style="text-align: left; padding: 0 4px 3px 4px; text-transform: uppercase;">Driver:</td>
                    <td style="text-align: right; padding: 0 4px 3px 4px; text-transform: uppercase;">\${data.driverName || 'N/A'}</td>
                  </tr>
